        c.setOwner(newOwner);

        vm.prank(callerAfter);
        try c.setOwner(callerAfter) {
            // allowed
        } catch {
            // reverted: correct behaviour
        }

        assertTrue(c.owner() == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner, address caller, address newVal) public {
        // admin is the deployer of c, i.e. this test contract
        address admin = address(this);
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != admin);
        vm.assume(caller != admin);
        vm.assume(newVal != newOwner);
        vm.assume(newVal != address(0));

        // admin sets owner to newOwner (always succeeds in both versions)
        c.setOwner(newOwner);

        // a non-admin caller attempts to change owner
        vm.prank(caller);
        bool ok;
        try c.setOwner(newVal) { ok = true; } catch { ok = false; }

        // rule: only the admin can ever change owner, so a non-admin call must
        // leave owner unchanged (regardless of ok; here it always reverts in P)
        assertTrue(c.owner() == newOwner, "non-admin must not change owner");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok;
        bool returned = true;
        // low-level call so a revert (non-admin) is observed as false, not a failed test
        (bool success, bytes memory data) = address(c).call(
            abi.encodeWithSelector(c.setOwner.selector, newOwner)
        );
        if (success) {
            ok = true;
            returned = abi.decode(data, (bool));
        } else {
            ok = false;
        }
        if (ok) {
            // General rule: any successful setOwner call returns true and updates owner.
            assertTrue(returned == true && c.owner() == newOwner);
        } else {
            // Non-admin calls must revert; then owner stays msg.sender of deployer.
            assertTrue(c.owner() != address(0));
        }
    }
}

